code.source:
#include <iostream>
using namespace std;

int main() {
    const int max_seats = 40;
    constexpr double pi = 3.14159;
    auto fare = 25.5;
    auto seats = 12;
    cout << "Max: " << max_seats << endl;
    cout << "Fare: " << fare * seats << endl;
    cout << "Pi: " << pi << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    constexpr double pi = 3.14159;
    const double radius = 2.0;
    auto area = pi * radius * radius;
    cout << "Area: " << area << endl;
    return 0;
}

